      <wj-button [label]="severity" [severity]="severity" />
    }
  `,
})
export class ButtonSeveritiesExample {
  protected readonly severities: readonly WjButtonSeverity[] = [
    'primary',
    'secondary',
    'success',
    'info',
    'warn',
    'danger',
    'help',
    'contrast',
  ];
}

